#endif
void CC_TRANSFER_FOG_BASE(vec4 pos, out float factor)
{
#if CC_USE_FOG == 0
	factor = LinearFog(pos, cc_cameraPos.xyz, cc_fogBase.x, cc_fogBase.y);
#elif CC_USE_FOG == 1
	factor = ExpFog(pos, cc_cameraPos.xyz, cc_fogBase.x, cc_fogBase.z, cc_fogAdd.z);
#elif CC_USE_FOG == 2
	factor = ExpSquaredFog(pos, cc_cameraPos.xyz, cc_fogBase.x, cc_fogBase.z, cc_fogAdd.z);
#elif CC_USE_FOG == 3
	factor = LayeredFog(pos, cc_cameraPos.xyz, cc_fogAdd.x, cc_fogAdd.y, cc_fogAdd.z);
#else
	factor = 1.0;
#endif
}
void CC_APPLY_FOG_BASE(inout vec4 color, float factor) {
	color = vec4(mix(cc_fogColor.rgb, color.rgb, factor), color.a);
}
#if !CC_USE_ACCURATE_FOG
varying mediump float v_fog_factor;
#endif
void CC_APPLY_FOG(inout vec4 color) {
#if !CC_USE_ACCURATE_FOG
    CC_APPLY_FOG_BASE(color, v_fog_factor);
#endif
}
void CC_APPLY_FOG(inout vec4 color, vec3 worldPos) {
#if CC_USE_ACCURATE_FOG
    float factor;
    CC_TRANSFER_FOG_BASE(vec4(worldPos, 1.0), factor);
#else
    float factor = v_fog_factor;
#endif
    CC_APPLY_FOG_BASE(color, factor);
}
varying vec2 v_uv;
varying float v_fade;
varying vec3 v_worldPos;
  uniform vec4 foamColor;
  uniform vec4 wetColor;
  uniform vec4 bandParams;
  uniform vec4 lineParams;
  uniform vec4 swash;
  uniform vec4 cycle;
  uniform vec4 tint;
  uniform vec4 lightParams;
float frontAt (float ph) {
  return smoothstep(0.0, cycle.y, ph) * (1.0 - smoothstep(cycle.y, 1.0, ph));
}
vec4 frag () {
  float u = v_uv.x, v = v_uv.y;
  #if USE_CC_TIME
    float t = cc_time.x;
    float ph = fract(t / cycle.x);
    float front = frontAt(ph);
    float foamA = smoothstep(0.0, 0.12, ph) * (1.0 - smoothstep(cycle.y + 0.15, 0.95, ph));
    float wet = 0.35 + 0.65 * frontAt(fract(ph - cycle.z));
  #else
    float t = swash.w;
    float front = swash.x, foamA = swash.y, wet = swash.z;
  #endif
  float s0 = bandParams.x, reach = bandParams.y;
  float dist = length(cc_cameraPos.xyz - v_worldPos);
  float far = smoothstep(lightParams.z, lightParams.w, dist);
  float b = 0.62 + 0.38 * sin(u * lineParams.z + 1.7 * sin(u * 0.31 * lineParams.z + t * 6.2831853 / cycle.x));
  float fv = s0 + reach * front;
  float w = bandParams.z * (1.0 + 1.5 * far);
  float lip = smoothstep(fv - w, fv - 0.3 * w, v) * (1.0 - smoothstep(fv - 0.015, fv + 0.012, v));
  float trail = smoothstep(s0 - 0.05, fv, v) * (1.0 - smoothstep(fv - 0.015, fv + 0.012, v)) * 0.12;
  float foam = (lip * b + trail) * foamA;
  float ln = fract(v * lineParams.x - t * lineParams.y);
  float line = smoothstep(0.80, 0.95, ln) * (1.0 - smoothstep(0.95, 1.0, ln));
  line *= smoothstep(0.04, 0.24, v) * (1.0 - smoothstep(s0 - 0.10, s0 + 0.01, v)) * lineParams.w * (0.55 + 0.45 * b) * (1.0 - far);
  float wv = s0 + reach * wet;
  float wetA = wetColor.a * smoothstep(s0 - 0.04, s0 + 0.03, v) * (1.0 - smoothstep(wv - bandParams.w, wv + 0.02, v));
  float fa = clamp(foam + line, 0.0, foamColor.a);
  float a = fa + wetA * (1.0 - fa);
  vec3 albedo = (foamColor.rgb * fa + wetColor.rgb * wetA * (1.0 - fa)) / max(a, 1e-4);
  a *= v_fade * tint.a * smoothstep(0.0, 0.06, v) * (1.0 - smoothstep(0.94, 1.0, v));
  #if USE_LIT
    vec3 L = normalize(-cc_mainLitDir.xyz);
    float NL = max(L.y, 0.0);
    vec3 lit = cc_mainLitColor.rgb * cc_mainLitColor.w;
    vec3 amb = cc_ambientSky.rgb * cc_ambientSky.w;
    vec3 col = min(albedo * (lit * NL / 3.14159265 * lightParams.x + amb * lightParams.y), albedo) * tint.rgb;
  #else
    vec3 col = albedo * tint.rgb;
  #endif
  vec4 o = vec4(col, a);
  CC_APPLY_FOG(o, v_worldPos);
  o = CCFragOutput(o);
  o.rgb *= o.a;
  return o;
}
void main() { gl_FragColor = frag(); }
